import{_ as t,a as o,b as a,c as r,d as n}from"./chunks/ai-tutor-preview-4.D4j7LDzW.js";import{_ as i,o as s,c as l,aj as u}from"./chunks/framework.C6uXqnaX.js";const b=JSON.parse('{"title":"Angular AI Tutor","description":"","frontmatter":{"untranslated":true},"headers":[],"relativePath":"ai/ai-tutor.md","filePath":"ai/ai-tutor.md"}'),h={name:"ai/ai-tutor.md"};function c(p,e,g,d,m,y){return s(),l("div",null,e[0]||(e[0]=[u('<h1 id="angular-ai-tutor" tabindex="-1">Angular AI Tutor <a class="header-anchor" href="#angular-ai-tutor" aria-label="Permalink to &quot;Angular AI Tutor&quot;">​</a></h1><p>The Angular AI Tutor is designed to interactively guide you step-by-step through building a complete, modern Angular application from the ground up. You&#39;ll learn the latest patterns and best practices by building a real, tangible project: a <strong>&quot;Smart Recipe Box&quot;</strong> for creating and managing recipes.</p><p>Our goal is to foster critical thinking and help you retain what you learn. Instead of just giving you code, the tutor will explain concepts, show you examples, and then give you project-specific exercises to solve on your own.</p><h2 id="get-started" tabindex="-1">Get Started <a class="header-anchor" href="#get-started" aria-label="Permalink to &quot;Get Started&quot;">​</a></h2><p>You can access the AI tutor via the <a href="/ai/mcp">Angular MCP server</a>.</p><ol><li><a href="/ai/mcp#get-started">Install</a> the Angular MCP server</li><li>Create a new Angular project <code>ng new &lt;project-name&gt;</code></li><li>Navigate to your new project (<code>cd &lt;project-name&gt;</code>) in an AI-powered editor or tool, like the <a href="https://geminicli.com/" target="_blank" rel="noreferrer">Gemini CLI</a></li><li>Enter a prompt like <code>launch the Angular AI tutor</code><img src="'+t+'" alt="A screenshot demonstrating how to launch the Angular AI Tutor in the Gemini CLI." title="Launch the Angular AI Tutor"></li></ol><h2 id="using-the-ai-tutor" tabindex="-1">Using the AI Tutor <a class="header-anchor" href="#using-the-ai-tutor" aria-label="Permalink to &quot;Using the AI Tutor&quot;">​</a></h2><p>Each module begins with a brief concept explanation. <img src="'+o+'" alt="A screenshot of the Angular AI Tutor presenting a brief concept explanation." title="Angular AI Tutor explanation"> If applicable, the tutor will present a code example to demonstrate the concept. <img src="'+a+'" alt="A screenshot of the Angular AI Tutor showing a code example." title="Angular AI Tutor code example"> The tutor will also provide an open-ended exercise to test your understanding. <img src="'+r+'" alt="A screenshot of the Angular AI Tutor providing an exercise." title="Angular AI Tutor exercise"> Finally, the tutor will check your work before moving onto the next module. <img src="'+n+`" alt="A screenshot of the Angular AI Tutor checking the user&#39;s work." title="Angular AI Tutor check"></p><h2 id="how-it-works-the-learning-cycle" tabindex="-1">How It Works: The Learning Cycle <a class="header-anchor" href="#how-it-works-the-learning-cycle" aria-label="Permalink to &quot;How It Works: The Learning Cycle&quot;">​</a></h2><p>For each new topic, you&#39;ll follow a learning loop that emphasizes critical thinking to help you better retain what you learn.</p><ol><li><strong>Learn the Concept:</strong> The tutor will briefly explain a core Angular feature and show you a generic code example to illustrate it.</li><li><strong>Apply Your Knowledge:</strong> You&#39;ll immediately get a hands-on exercise. The tutor presents these exercises at a high level with objectives and expected outcomes, encouraging you to think through the solution yourself.</li><li><strong>Get Feedback &amp; Support:</strong> When you&#39;re ready, let the tutor know. It will <strong>automatically read your project files</strong> to verify your solution is correct. If you get stuck, you are in complete control. You can ask for a <strong>&quot;hint&quot;</strong> for more guidance, or get step-by-step instructions by typing <strong>&quot;detailed guide&quot;</strong> or <strong>&quot;step-by-step instructions.&quot;</strong></li></ol><p>Once you&#39;ve succeeded, the tutor will move directly to the next topic. You can also ask the tutor for more information on a topic or ask any related Angular questions at any time.</p><hr><h2 id="features-commands" tabindex="-1"><strong>Features &amp; Commands</strong> <a class="header-anchor" href="#features-commands" aria-label="Permalink to &quot;**Features &amp; Commands**&quot;">​</a></h2><p>You are in control of your learning experience. Use these features at any time:</p><h3 id="leave-and-come-back" tabindex="-1"><strong>Leave and Come Back</strong> <a class="header-anchor" href="#leave-and-come-back" aria-label="Permalink to &quot;**Leave and Come Back**&quot;">​</a></h3><p>Feel free to take a break. Your progress is tied to your project&#39;s code. When you return for a new session, the tutor will automatically analyze your files to determine exactly where you left off, allowing you to seamlessly pick up right where you were.</p><p><strong>Pro Tip:</strong> We highly recommend using Git to save your progress. After completing a module, it&#39;s a great idea to commit your changes (e.g., <code>git commit -m &quot;Complete Phase 1, Module 8&quot;</code>). This acts as a personal checkpoint you can always return to.</p><h3 id="adjust-your-experience-level" tabindex="-1"><strong>Adjust Your Experience Level</strong> <a class="header-anchor" href="#adjust-your-experience-level" aria-label="Permalink to &quot;**Adjust Your Experience Level**&quot;">​</a></h3><p>You can set your experience level to <strong>Beginner (1-3)</strong>, <strong>Intermediate (4-7)</strong>, or <strong>Experienced (8-10)</strong>. You can change this setting at any time during your session, and the tutor will immediately adapt its teaching style to match.</p><p><strong>Example Prompts:</strong></p><ul><li>&quot;Set my experience level to beginner.&quot;</li><li>&quot;Change my rating to 8.&quot;</li></ul><h3 id="see-the-full-learning-plan" tabindex="-1"><strong>See the Full Learning Plan</strong> <a class="header-anchor" href="#see-the-full-learning-plan" aria-label="Permalink to &quot;**See the Full Learning Plan**&quot;">​</a></h3><p>Want to see the big picture or check how far you&#39;ve come? Just ask for the table of contents.</p><p><strong>Example Prompts:</strong></p><ul><li>&quot;Where are we?&quot;</li><li>&quot;Show the table of contents.&quot;</li><li>&quot;Show the plan.&quot;</li></ul><p>The tutor will display the full learning plan and mark your current location.</p><h3 id="a-note-on-styling" tabindex="-1"><strong>A Note on Styling</strong> <a class="header-anchor" href="#a-note-on-styling" aria-label="Permalink to &quot;**A Note on Styling**&quot;">​</a></h3><p>The tutor will apply basic styling to your application to keep things looking clean. You are highly encouraged to apply your own styling to make the app your own.</p><h3 id="skip-the-current-module" tabindex="-1"><strong>Skip the Current Module</strong> <a class="header-anchor" href="#skip-the-current-module" aria-label="Permalink to &quot;**Skip the Current Module**&quot;">​</a></h3><p>If you&#39;d rather move on to the next topic in the learning path, you can ask the tutor to skip the current exercise.</p><p><strong>Example Prompts:</strong></p><ul><li>&quot;Skip this section.&quot;</li><li>&quot;Auto-complete this step for me.&quot;</li></ul><p>The tutor will ask for confirmation and then present you with the complete code solution for the current module and attempt to automatically apply any required updates to ensure you can continue smoothly with the next module.</p><h3 id="jump-to-any-topic" tabindex="-1"><strong>Jump to Any Topic</strong> <a class="header-anchor" href="#jump-to-any-topic" aria-label="Permalink to &quot;**Jump to Any Topic**&quot;">​</a></h3><p>If you want to learn about a specific topic out of order (e.g., jump from the basics to forms), you can. The tutor will provide the necessary code to update your project to the correct starting point for the selected module and attempt to automatically apply any required updates.</p><p><strong>Example Prompts:</strong></p><ul><li>&quot;Take me to the forms lesson.&quot;</li><li>&quot;I want to learn about Route Guards now.&quot;</li><li>&quot;Jump to the section on Services.&quot;</li></ul><hr><h2 id="troubleshooting" tabindex="-1"><strong>Troubleshooting</strong> <a class="header-anchor" href="#troubleshooting" aria-label="Permalink to &quot;**Troubleshooting**&quot;">​</a></h2><h3 id="setup-issues" tabindex="-1">Setup Issues <a class="header-anchor" href="#setup-issues" aria-label="Permalink to &quot;Setup Issues&quot;">​</a></h3><p><strong>&quot;launch the Angular AI tutor&quot; doesn&#39;t do anything?</strong></p><p>Make sure you have a project open first. The tutor needs an actual Angular project to work with:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">ng</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> new</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> my-app</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">cd</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> my-app</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">code</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> .</span></span></code></pre></div><p>Then ensure your MCP server is running. In VS Code, open the <code>.vscode/mcp.json</code> file and click the <strong>&quot;Start&quot;</strong> button at the top of the file.</p><p>When you type &quot;launch the Angular AI tutor&quot;, you should see a checkmark saying &quot;Reviewed .vscode/mcp.json and ran start task&quot; and a prompt asking to &quot;Allow task run?&quot; — go ahead and click Allow.</p><p><strong>Still not working?</strong></p><p>Try typing <code>#angular-cli</code> first to load the Angular context, then paste the tutorial URL: <code>https://angular.dev/ai/ai-tutor</code></p><p><strong>How to verify the server is running</strong></p><p>Open the Command Palette (<code>Ctrl+Shift+P</code>), type &quot;MCP: List Running Servers&quot;, and look for &quot;angular-cli&quot; in the list.</p><hr><h3 id="general-issues" tabindex="-1">General Issues <a class="header-anchor" href="#general-issues" aria-label="Permalink to &quot;General Issues&quot;">​</a></h3><p>If the tutor doesn&#39;t respond correctly or you suspect an issue with your application, here are a few things to try:</p><ol><li><strong>Type &quot;proceed&quot;:</strong> This can often nudge the tutor to continue to the next step in the event it gets stuck.</li><li><strong>Correct the Tutor:</strong> If the tutor is mistaken about your progress (e.g., it says you&#39;re on Module 3 but you&#39;ve completed Module 8), just tell it. For example: <em>&quot;I&#39;m actually on Module 8.&quot;</em> The tutor will re-evaluate your code and adjust.</li><li><strong>Verify Your UI:</strong> If you want to confirm what your application&#39;s user interface should look like, just ask the tutor. For example: <em>&quot;What should I see in my UI?&quot;</em></li><li><strong>Reload the Browser Window:</strong> A refresh can solve many issues related to your application.</li><li><strong>Hard Restart the Browser:</strong> Errors are sometimes only surfaced in the browser&#39;s developer console. A hard restart can help clear underlying issues related to the application.</li><li><strong>Start a New Chat:</strong> You can always start a new chat to remove the existing history and begin fresh. The tutor will read your files to find the latest step you were on.</li></ol><h2 id="your-learning-journey-the-phased-path" tabindex="-1"><strong>Your Learning Journey: The Phased Path</strong> <a class="header-anchor" href="#your-learning-journey-the-phased-path" aria-label="Permalink to &quot;**Your Learning Journey: The Phased Path**&quot;">​</a></h2><p>You will build your application over a five-phase journey. You can follow this path from start to finish to create a complete, fully-functional Angular application. Each module builds logically upon the last, taking you from the basics to advanced, real-world features.</p><p><strong>A Note on Automated Setup:</strong> Some modules require a setup step, like creating interfaces or mock data. In these cases, the tutor will present you with the code and file instructions. You will be responsible for creating and modifying these files as instructed before the exercise begins.</p><h3 id="phase-1-angular-fundamentals" tabindex="-1"><strong>Phase 1: Angular Fundamentals</strong> <a class="header-anchor" href="#phase-1-angular-fundamentals" aria-label="Permalink to &quot;**Phase 1: Angular Fundamentals**&quot;">​</a></h3><ul><li><strong>Module 1:</strong> Getting Started</li><li><strong>Module 2:</strong> Dynamic Text with Interpolation</li><li><strong>Module 3:</strong> Event Listeners (<code>(click)</code>)</li></ul><h3 id="phase-2-state-and-signals" tabindex="-1"><strong>Phase 2: State and Signals</strong> <a class="header-anchor" href="#phase-2-state-and-signals" aria-label="Permalink to &quot;**Phase 2: State and Signals**&quot;">​</a></h3><ul><li><strong>Module 4:</strong> State Management with Writable Signals (Part 1: <code>set</code>)</li><li><strong>Module 5:</strong> State Management with Writable Signals (Part 2: <code>update</code>)</li><li><strong>Module 6:</strong> Computed Signals</li></ul><h3 id="phase-3-component-architecture" tabindex="-1"><strong>Phase 3: Component Architecture</strong> <a class="header-anchor" href="#phase-3-component-architecture" aria-label="Permalink to &quot;**Phase 3: Component Architecture**&quot;">​</a></h3><ul><li><strong>Module 7:</strong> Template Binding (Properties &amp; Attributes)</li><li><strong>Module 8:</strong> Creating &amp; Nesting Components</li><li><strong>Module 9:</strong> Component Inputs with Signals</li><li><strong>Module 10:</strong> Styling Components</li><li><strong>Module 11:</strong> List Rendering with <code>@for</code></li><li><strong>Module 12:</strong> Conditional Rendering with <code>@if</code></li></ul><h3 id="phase-4-advanced-features-architecture" tabindex="-1"><strong>Phase 4: Advanced Features &amp; Architecture</strong> <a class="header-anchor" href="#phase-4-advanced-features-architecture" aria-label="Permalink to &quot;**Phase 4: Advanced Features &amp; Architecture**&quot;">​</a></h3><ul><li><strong>Module 13:</strong> Two-Way Binding</li><li><strong>Module 14:</strong> Services &amp; Dependency Injection (DI)</li><li><strong>Module 15:</strong> Basic Routing</li><li><strong>Module 16:</strong> Introduction to Forms</li><li><strong>Module 17:</strong> Intro to Angular Material</li></ul><h3 id="phase-5-signal-forms" tabindex="-1"><strong>Phase 5: Signal Forms</strong> <a class="header-anchor" href="#phase-5-signal-forms" aria-label="Permalink to &quot;**Phase 5: Signal Forms**&quot;">​</a></h3><ul><li><strong>Module 18</strong>: <strong>Introduction to Signal Forms</strong></li><li><strong>Module 19</strong>: <strong>Submitting &amp; Resetting</strong></li><li><strong>Module 20</strong>: <strong>Validation in Signal Forms</strong></li><li><strong>Module 21</strong>: <strong>Field State &amp; Error Messages</strong></li></ul><hr><h2 id="a-note-on-ai-feedback" tabindex="-1"><strong>A Note on AI &amp; Feedback</strong> <a class="header-anchor" href="#a-note-on-ai-feedback" aria-label="Permalink to &quot;**A Note on AI &amp; Feedback**&quot;">​</a></h2><p>This tutor is powered by a Large Language Model (LLM). While we&#39;ve worked hard to make it an expert, AIs can make mistakes. If you encounter an explanation or code example that seems incorrect, please let us know. You can correct the tutor, and it will use your feedback to adjust its response.</p><p>For any technical bugs or feature requests, please <a href="https://github.com/angular/angular-cli/issues" target="_blank" rel="noreferrer">submit an issue</a>.</p>`,71)]))}const q=i(h,[["render",c]]);export{b as __pageData,q as default};
